import React, { useEffect, useState } from 'react';
import { supabase } from '../supabase';
import DashboardLayout from './DashboardLayout';

// Add ContentRenderer component
function ContentRenderer({ darkMode, activeMenu }) {
  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard':
        return (
          <div className={`p-4 ${darkMode ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow`}>
            <h2 className={`text-xl font-semibold mb-4 ${darkMode ? 'text-white' : 'text-gray-900'}`}>
              Getting Started
            </h2>
            <p className={darkMode ? 'text-gray-300' : 'text-gray-700'}>
              Welcome to your dashboard! You've successfully logged in to your account.
            </p>
          </div>
        );
      case 'team':
        return (
          <div className={`p-4 ${darkMode ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow`}>
            <h2 className={`text-xl font-semibold mb-4 ${darkMode ? 'text-white' : 'text-gray-900'}`}>
              Team Management
            </h2>
            <p className={darkMode ? 'text-gray-300' : 'text-gray-700'}>
              Manage your team members and their permissions here.
            </p>
          </div>
        );
      case 'projects':
        return (
          <div className={`p-4 ${darkMode ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow`}>
            <h2 className={`text-xl font-semibold mb-4 ${darkMode ? 'text-white' : 'text-gray-900'}`}>
              Projects Overview
            </h2>
            <p className={darkMode ? 'text-gray-300' : 'text-gray-700'}>
              View and manage all your ongoing projects.
            </p>
          </div>
        );
      case 'calendar':
        return (
          <div className={`p-4 ${darkMode ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow`}>
            <h2 className={`text-xl font-semibold mb-4 ${darkMode ? 'text-white' : 'text-gray-900'}`}>
              Calendar
            </h2>
            <p className={darkMode ? 'text-gray-300' : 'text-gray-700'}>
              Schedule and manage your appointments and deadlines.
            </p>
          </div>
        );
      case 'feature1':
        return (
          <div className={`p-4 ${darkMode ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow`}>
            <h2 className={`text-xl font-semibold mb-4 ${darkMode ? 'text-white' : 'text-gray-900'}`}>
              Feature 1
            </h2>
            <p className={darkMode ? 'text-gray-300' : 'text-gray-700'}>
              This is Feature 1. Add your content and functionality here.
            </p>
          </div>
        );

      default:
        return null;
    }
  };

  return renderContent();
}

function Dashboard() {
  const [loading, setLoading] = useState(true);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('darkMode') === 'true');
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const toggleSidebar = () => {
    setSidebarOpen(!isSidebarOpen);
  };

  const [activeMenu, setActiveMenu] = useState('dashboard');

  useEffect(() => {
    checkUser();
  }, []);

  const checkUser = async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        window.location.replace('/login');
        return;
      }
    } catch (error) {
      console.error('Session error:', error);
      window.location.replace('/login');
    } finally {
      setLoading(false);
    }
  };

  const handleSignOut = async () => {
    try {
      await supabase.auth.signOut();
      window.location.replace('/login');
    } catch (error) {
      console.error('Error:', error);
      window.location.replace('/login');
    }
  };

  const toggleDarkMode = () => {
    setDarkMode(prev => {
      const newMode = !prev;
      localStorage.setItem('darkMode', newMode);
      return newMode;
    });
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-r from-gray-100 to-gray-200 dark:from-gray-800 dark:to-gray-900">
        <div className="text-xl text-gray-600 dark:text-gray-200">Loading...</div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${darkMode ? 'dark' : ''}`}>
      {/* Mobile Menu Button */}
      <button
        onClick={toggleSidebar}
        className={`md:hidden fixed top-4 left-4 z-20 p-2 rounded-md bg-gray-800 text-white ${
          isSidebarOpen ? 'opacity-0' : 'opacity-100'
        } transition-opacity duration-300`}
      >
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
        </svg>
      </button>

      <DashboardLayout
        darkMode={darkMode}
        toggleDarkMode={toggleDarkMode}
        isSidebarOpen={isSidebarOpen}
        toggleSidebar={toggleSidebar}
        activeMenu={activeMenu}
        setActiveMenu={setActiveMenu}
        handleSignOut={handleSignOut}
      >
        <ContentRenderer darkMode={darkMode} activeMenu={activeMenu} />
      </DashboardLayout>
    </div>
  );
}

export default Dashboard;
